        public void Print(
            INpcGetter item,
            StructuredStringBuilder sb,
            string? name = null,
            Npc.Mask<bool>? printMask = null)
        {
            if (name == null)
            {
                sb.AppendLine($"Npc =>");
            }
            else
            {
                sb.AppendLine($"{name} (Npc) =>");
            }
            using (sb.Brace())
            {
                ToStringFields(
                    item: item,
                    sb: sb,
                    printMask: printMask);
            }
        }
        
