        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(INpcGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.PreviewTransform, out var PreviewTransformInfo))
            {
                yield return PreviewTransformInfo;
            }
            if (FormLinkInformation.TryFactory(obj.AnimationSound, out var AnimationSoundInfo))
            {
                yield return AnimationSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SnapTemplate, out var SnapTemplateInfo))
            {
                yield return SnapTemplateInfo;
            }
            if (FormLinkInformation.TryFactory(obj.DefaultLayer, out var DefaultLayerInfo))
            {
                yield return DefaultLayerInfo;
            }
            if (FormLinkInformation.TryFactory(obj.AdjustJiggleNerveGlobal, out var AdjustJiggleNerveGlobalInfo))
            {
                yield return AdjustJiggleNerveGlobalInfo;
            }
            if (FormLinkInformation.TryFactory(obj.AdjustJiggleXGlobal, out var AdjustJiggleXGlobalInfo))
            {
                yield return AdjustJiggleXGlobalInfo;
            }
            if (FormLinkInformation.TryFactory(obj.AdjustJiggleOffsetGlobal, out var AdjustJiggleOffsetGlobalInfo))
            {
                yield return AdjustJiggleOffsetGlobalInfo;
            }
            if (FormLinkInformation.TryFactory(obj.DeathItem, out var DeathItemInfo))
            {
                yield return DeathItemInfo;
            }
            if (FormLinkInformation.TryFactory(obj.VoiceType, out var VoiceTypeInfo))
            {
                yield return VoiceTypeInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Template, out var TemplateInfo))
            {
                yield return TemplateInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LegendaryTemplate, out var LegendaryTemplateInfo))
            {
                yield return LegendaryTemplateInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LegendaryChance, out var LegendaryChanceInfo))
            {
